canonical_solution:
def top_symbol(text: str) -> str:
    """Return the character that occurs most often in `text`.

    Only ASCII letters (a-z, A-Z) are counted; every other character is ignored.
    Counting is case-sensitive: 'A' and 'a' are different characters.
    If several characters share the highest count, return the smallest one in ordinary string order (code point).
    If no character is counted, return ''.

    >>> top_symbol('Mississippi')
    'i'
    """
    counts = {}
    for ch in text:
        if not (ch.isascii() and ch.isalpha()):
            continue
        counts[ch] = counts.get(ch, 0) + 1
    if not counts:
        return ""
    best = max(counts.values())
    cands = [c for c in counts if counts[c] == best]
    return min(cands)

