canonical_solution:
def reverse_lookup(mapping: dict[str, int]) -> dict:
    """Invert `mapping` (str keys, int values): each distinct value becomes a key that
    maps to the LIST of all keys that had it, in the dict's insertion order.

    Values that occur only once still map to a one-element list.
    An empty mapping gives {}.

    >>> reverse_lookup({'a': 1, 'b': 2, 'c': 1})
    {1: ['a', 'c'], 2: ['b']}
    """
    out = {}
    for k, v in mapping.items():
        out.setdefault(v, []).append(k)
    return out

