def order_records(records: list[tuple[str, int, int]]) -> list[str]:
    """Each record is a (name, age, score) tuple. Return the names ordered by:

    1. score descending;
    2. then, among equal score, by age descending;
    3. records equal on both keys keep their original relative order.

    An empty list gives [].

    >>> order_records([('ann', 30, 5), ('bo', 25, 9), ('cy', 30, 9)])
    ['cy', 'bo', 'ann']
