def is_well_nested(text: str) -> bool:
    """Check the brackets in `text`. The bracket pairs are '{}', '()'; every other
    character (including any other bracket-like character) is ignored.

    Return True if the brackets are balanced and properly nested, else False.

    >>> is_well_nested('{()}')
    True
    """
    pairs = {'}': '{', ')': '('}
    stack = []
    depth = 0
    for i, ch in enumerate(text):
        if ch in '{(':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

