def index_words(words: list[str]) -> dict:
    """Group the non-empty strings in `words` by their length.

    Return a dict mapping each key to the list of words having that key,
    sorted in ascending string order (case-sensitive; duplicates kept). Words keep their original spelling. Empty strings are ignored;
    an empty input gives {}.

    >>> index_words(['ant', 'Bee', 'art', 'bat'])
    {3: ['Bee', 'ant', 'art', 'bat']}
    """
    groups = {}
    for w in words:
        if not w:
            continue
        key = len(w)
        groups.setdefault(key, []).append(w)
    for k in groups:
        groups[k] = sorted(groups[k])
    return groups

