canonical_solution:
def invert_mapping(mapping: dict[str, int]) -> dict:
    """Invert `mapping` (str keys, int values): each distinct value becomes a key that
    maps to the list of all keys that had it, sorted in ascending order.

    Values that occur only once still map to a one-element list.
    An empty mapping gives {}.

    >>> invert_mapping({'a': 1, 'b': 2, 'c': 1})
    {1: ['a', 'c'], 2: ['b']}
    """
    out = {}
    for k, v in mapping.items():
        out.setdefault(v, []).append(k)
    return {v: sorted(ks) for v, ks in out.items()}

